}

fn apply_component_projection_event(
    turns: &mut Vec<Turn>,
    pinned: &mut Vec<PinnedWidget>,
    event: &AgentEvent,
) {
    match event {
        AgentEvent::ComponentRender {
            component_id,
            kind,
            props,
            replace,
            ..
        } => {
            if component_placement(props) == ComponentPlacement::Pinned {
                upsert_pinned(
                    pinned,
                    PinnedWidget {
                        component_id: component_id.clone(),
                        kind: kind.clone(),
                        props: props.clone(),
                    },
                );
                return;
            }
            if *replace {
                for turn in turns.iter_mut() {
                    for block in turn.blocks.iter_mut() {
                        if matches!(block, Block::Component { component_id: id, .. } if id == component_id)
                        {
                            *block = Block::Component {
                                component_id: component_id.clone(),
                                kind: kind.clone(),
                                props: props.clone(),
                            };
                            return;
                        }
                    }
                }
            }
            ensure_component_turn(turns).blocks.push(Block::Component {
                component_id: component_id.clone(),
                kind: kind.clone(),
                props: props.clone(),
            });
        }
        AgentEvent::ComponentUnmount { component_id, .. } => {
            for turn in turns.iter_mut() {
                turn.blocks.retain(|block| {
                    !matches!(block, Block::Component { component_id: id, .. } if id == component_id)
                });
            }
            turns.retain(|turn| !turn.blocks.is_empty());
            pinned.retain(|widget| widget.component_id != *component_id);
        }
        _ => {}
    }
}

fn apply_projection_content(
    turns: &mut Vec<Turn>,
    pinned: &mut Vec<PinnedWidget>,
    event: &AgentEvent,
) {
    match event {
        AgentEvent::AssistantTextDelta { turn_id, delta, .. } => {
            let turn = ensure_assistant_turn(turns, turn_id);
            match turn.blocks.last_mut() {
                Some(Block::Text(text)) => text.push_str(delta),
                _ => turn.blocks.push(Block::Text(delta.clone())),
            }
        }
        AgentEvent::ThinkingDelta { turn_id, delta, .. } => {
            let turn = ensure_assistant_turn(turns, turn_id);
            match turn.blocks.last_mut() {
                Some(Block::Thinking { content, .. }) => content.push_str(delta),
                _ => turn.blocks.push(Block::Thinking {
                    content: delta.clone(),
                    expanded: false,
                }),
            }
        }
        AgentEvent::ToolCallStarted { turn_id, call, .. } => {
            let args = serde_json::to_string(&call.args_json).unwrap_or_else(|_| "{}".into());
            ensure_assistant_turn(turns, turn_id)
                .blocks
                .push(Block::ToolCall {
                    call_id: call.id.clone(),
                    name: call.name.clone(),
                    args_preview: args.chars().take(60).collect(),
                    output: String::new(),
                    status: ToolStatus::Running,
                    expanded: false,
                });
        }
        AgentEvent::ToolCallChunk {
            turn_id,
            call_id,
            chunk,
            ..
        } => {
            for block in ensure_assistant_turn(turns, turn_id)
                .blocks
                .iter_mut()
                .rev()
            {
                if let Block::ToolCall {
                    call_id: id,
                    output,
                    ..
                } = block
                {
                    if id == call_id {
                        output.push_str(chunk);
                        break;
                    }
                }
            }
        }
        AgentEvent::ToolCallFinished {
            turn_id,
            call_id,
            result,
            ..
        } => {
            for block in ensure_assistant_turn(turns, turn_id)
                .blocks
                .iter_mut()
                .rev()
            {
                if let Block::ToolCall {
                    call_id: id,
                    output,
                    status,
                    expanded,
                    ..
                } = block
                {
                    if id == call_id {
                        if output.is_empty() {
                            output.push_str(&result.output);
                        }
                        *status = if result.ok {
                            ToolStatus::Ok
                        } else {
                            ToolStatus::Err
                        };
                        *expanded |= !result.ok;
                        break;
                    }
                }
            }
        }
        AgentEvent::ComponentRender { .. } | AgentEvent::ComponentUnmount { .. } => {
            apply_component_projection_event(turns, pinned, event);
        }
        _ => {}
    }
}

type ProjectionReplacement = (Vec<Turn>, Vec<PinnedWidget>);

fn checkpoint_replacement(
    checkpoint: &SessionProjectionCheckpoint,
) -> Result<Option<ProjectionReplacement>, ProjectionPreparation> {
    match checkpoint {
        SessionProjectionCheckpoint::Inline {
            transcript,
            tool_context,
            ..
        } => Ok(Some(turns_from_session_transcript(
            transcript.clone(),
            tool_context,
        ))),
        SessionProjectionCheckpoint::Refetch { .. } => Err(ProjectionPreparation::Restart),
    }
}

fn permission_from_projection(value: &Value, session_id: &str) -> Option<PendingPermission> {
    let event = serde_json::from_value::<ControlEvent>(value.clone()).ok()?;
    match event {
        ControlEvent::PermissionRequest {
            permission_id: Some(permission_id),
            session_id: Some(event_session),
            tool,
            reason,
            args,
        } if event_session == session_id => Some(PendingPermission {
            permission_id,
            session_id: event_session,
            tool,
            reason,
            args_summary: summarize_args(&args),
            deciding: false,
        }),
        _ => None,
    }
}

fn prepare_projection_snapshot(
    detail: SessionDetail,
    projection: SessionProjection,
) -> Result<PreparedProjection, ProjectionPreparation> {
    if projection.version != 1
        || projection.lease_id.is_empty()
        || projection.lease_expires_ms <= 0
        || detail.persistence_revision != Some(projection.checkpoint_revision)
    {
        return Err(ProjectionPreparation::Invalid);
    }
    if let Some(checkpoint) = &projection.checkpoint {
        let revision = match checkpoint {
            SessionProjectionCheckpoint::Inline {
                persistence_revision,
                ..
            }
            | SessionProjectionCheckpoint::Refetch {
                persistence_revision,
            } => *persistence_revision,
        };
        if revision != projection.checkpoint_revision {
            return Err(ProjectionPreparation::Invalid);
        }
    }
    let final_cursor =
        parse_projection_cursor(&projection.cursor).ok_or(ProjectionPreparation::Invalid)?;
    if projection.pending_events.len() as u64 > final_cursor.seq {
        return Err(ProjectionPreparation::Invalid);
    }
    let mut expected_seq = final_cursor.seq - projection.pending_events.len() as u64;
    let (mut turns, mut pinned) =
        turns_from_session_transcript(detail.transcript.clone(), &detail.tool_context);

    // The top-level refetch marker is already satisfied by this same canonical
    // GET. Inline checkpoints are an aligned normalized replacement.
    if let Some(checkpoint) = &projection.checkpoint {
        if let SessionProjectionCheckpoint::Inline { .. } = checkpoint {
            if let Some(replacement) = checkpoint_replacement(checkpoint)? {
                (turns, pinned) = replacement;
            }
        }
    }

    for frame in &projection.pending_events {
        let parsed =
            parse_projection_cursor(&frame.cursor).ok_or(ProjectionPreparation::Invalid)?;
        expected_seq = expected_seq.saturating_add(1);
        if parsed.prefix != final_cursor.prefix || parsed.seq != expected_seq {
            return Err(ProjectionPreparation::Invalid);
        }
        match frame.source {
            SessionProjectionSource::Agent => {
                let event = serde_json::from_value::<AgentEvent>(frame.event.clone())
                    .map_err(|_| ProjectionPreparation::Invalid)?;
                if event.session_id() != Some(detail.id.as_str()) {
                    return Err(ProjectionPreparation::Invalid);
                }
                apply_projection_content(&mut turns, &mut pinned, &event);
            }
            SessionProjectionSource::Control => {
                // Folded permission state below is authoritative; reducing these
                // frames too would duplicate cards.
            }
            SessionProjectionSource::Checkpoint => {
                let checkpoint =
                    serde_json::from_value::<SessionProjectionCheckpoint>(frame.event.clone())
                        .map_err(|_| ProjectionPreparation::Invalid)?;
                if let Some(replacement) = checkpoint_replacement(&checkpoint)? {
                    (turns, pinned) = replacement;
                }
            }
        }
    }
    if expected_seq != final_cursor.seq {
        return Err(ProjectionPreparation::Invalid);
    }

    let decode_state = |value: &Option<Value>| {
        value
            .as_ref()
            .and_then(|value| serde_json::from_value::<AgentEvent>(value.clone()).ok())
            .filter(|event| event.session_id() == Some(detail.id.as_str()))
    };
    let permissions = projection
        .state
        .pending_permissions
        .iter()
        .filter_map(|value| permission_from_projection(value, &detail.id))
        .collect();

    Ok(PreparedProjection {
        active_turn: decode_state(&projection.state.active_turn),
        last_turn_finished: decode_state(&projection.state.last_turn_finished),
        model_rerouted: decode_state(&projection.state.model_rerouted),
        browser_active: projection.state.browser_active,
        detail,
        turns,
        pinned,
        cursor: projection.cursor,
        lease_id: projection.lease_id,
        permissions,
    })
}

