    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub checkpoint: Option<SessionProjectionCheckpoint>,
    /// Identified bounded replay lease required by the projection tail.
    pub lease_id: String,
    pub lease_expires_ms: i64,
    #[serde(default)]
    pub pending_events: Vec<SessionProjectionFrame>,
    #[serde(default)]
    pub state: SessionProjectionState,
}

