    /// Switch with an atomic daemon-owned projection attach. Every old transport
    /// is closed before the GET begins; the canonical snapshot and retained
    /// frames are installed as one batch before either live tail is opened.
    pub fn switch_session(&self, id: String, title: String) {
        let generation = self.sse_generation.get_untracked().wrapping_add(1);
        self.sse_generation.set(generation);
        self.agent_stream_ready.set(None);
        self.permission_stream_ready.set(None);
        self.planner_stream_sources
            .borrow_mut()
            .reset(id.clone(), generation);
        self.select_session_state(&id, title);
        self.spawn_projection_sync(id, generation);
    }

    fn spawn_projection_sync(&self, id: String, generation: u64) {
        let daemon = self.clone();
        spawn_local(async move {
            daemon.sync_session_projection(id, generation).await;
        });
    }

    fn projection_generation_is_current(&self, id: &str, generation: u64) -> bool {
        self.sse_generation.get_untracked() == generation
            && self.session_id.get_untracked().as_deref() == Some(id)
    }

    fn restart_projection(&self, id: &str, generation: u64, reason: &str) {
        if !self.projection_generation_is_current(id, generation) {
            return;
        }
        log::warn!("restarting session projection for {id}: {reason}");
        let next = generation.wrapping_add(1);
        self.sse_generation.set(next);
        self.planner_stream_sources
            .borrow_mut()
            .reset(id.to_string(), next);
        self.status.set("resyncing session…".into());
        self.spawn_projection_sync(id.to_string(), next);
    }

    async fn sync_session_projection(&self, id: String, generation: u64) {
        const PROJECTION_RETRIES: usize = 4;
        for attempt in 0..PROJECTION_RETRIES {
            if !self.projection_generation_is_current(&id, generation) {
                return;
            }
            let url = self.url.get_untracked();
            let get_url = format!("{}/v1/sessions/{id}", url.trim_end_matches('/'));
            let fetched = Request::get(&get_url).send().await;
            if !self.projection_generation_is_current(&id, generation) {
                return;
            }
            let response = match fetched {
                Ok(response) if response.ok() => {
                    let decoded = response.json::<SessionDetailResponse>().await;
                    if !self.projection_generation_is_current(&id, generation) {
                        return;
                    }
                    match decoded {
                        Ok(response) if response.ok => response,
                        Ok(response) => {
                            let error = response.error.unwrap_or_else(|| "unknown error".into());
                            self.status
                                .set(format!("session load failed: {}", concise_error(&error)));
                            return;
                        }
                        Err(error) => {
                            log::warn!("projection snapshot decode failed: {error}");
                            if attempt + 1 == PROJECTION_RETRIES {
                                self.status.set("session projection decode failed".into());
                                return;
                            }
                            gloo_timers::future::TimeoutFuture::new(75).await;
                            continue;
                        }
                    }
                }
                Ok(response) => {
                    let text = response.text().await.unwrap_or_default();
                    if !self.projection_generation_is_current(&id, generation) {
                        return;
                    }
                    self.status
                        .set(format!("session load failed: {}", concise_error(&text)));
                    return;
                }
                Err(error) => {
                    if attempt + 1 == PROJECTION_RETRIES {
                        self.status.set(format!(
                            "session load failed: {}",
                            concise_error(&error.to_string())
                        ));
                        return;
                    }
                    gloo_timers::future::TimeoutFuture::new(75).await;
                    continue;
                }
            };
            if !self.projection_generation_is_current(&id, generation) {
                return;
            }
            let Some(detail) = response.session else {
                self.status.set("session snapshot missing".into());
                return;
            };
            if detail.id != id {
                self.restart_projection(&id, generation, "snapshot session mismatch");
                return;
            }

            match response.projection {
                Some(projection) => match prepare_projection_snapshot(detail, projection) {
                    Ok(prepared) => {
                        if !self.install_projection_snapshot(&id, generation, prepared) {
                            return;
                        }
                        return;
                    }
                    Err(ProjectionPreparation::Restart | ProjectionPreparation::Invalid) => {
                        if attempt + 1 == PROJECTION_RETRIES {
                            self.restart_projection(
                                &id,
                                generation,
                                "invalid or refetch projection frame",
                            );
                            return;
                        }
                    }
                },
                None if detail.persistence_revision.is_none() => {
                    // Explicit old-daemon path. The complete hydrate precedes
                    // connect(), preserving the legacy best-effort ordering.
                    if !self.install_legacy_snapshot(&id, generation, detail) {
                        return;
                    }
                    self.status.set("legacy sync".into());
                    self.connect();
                    return;
                }
                None => {
                    // A new daemon can transiently expose the revision before
                    // its journal snapshot is ready. Retry rather than silently
                    // downgrading exactness on the first observation.
                    if attempt + 1 == PROJECTION_RETRIES {
                        if !self.install_legacy_snapshot(&id, generation, detail) {
                            return;
                        }
                        self.status.set("legacy sync".into());
                        self.connect();
                        return;
                    }
                }
            }
            gloo_timers::future::TimeoutFuture::new(75).await;
        }
    }

    fn install_legacy_snapshot(&self, id: &str, generation: u64, detail: SessionDetail) -> bool {
        if !self.projection_generation_is_current(id, generation) {
            return false;
        }
        let (turns, pinned) =
            turns_from_session_transcript(detail.transcript, &detail.tool_context);
        batch(|| {
            self.session_title.set(detail.title);
            if let Some(root) = detail
                .workspace_root
                .or(detail.cwd)
                .filter(|root| !root.is_empty())
            {
                self.cwd.set(root);
            }
            if !detail.model.is_empty() {
                self.model.set(Some(detail.model));
            }
            self.turns.set(turns);
            self.pinned_widgets.set(pinned);
            self.active_decision_token.set(None);
        });
        true
    }

    fn install_projection_snapshot(
        &self,
        id: &str,
        generation: u64,
        prepared: PreparedProjection,
    ) -> bool {
        if !self.projection_generation_is_current(id, generation) {
            return false;
        }
        let active = prepared.active_turn.as_ref().and_then(|event| match event {
            AgentEvent::TurnStarted { turn_id, model, .. } => {
                Some((turn_id.clone(), model.clone()))
            }
            _ => None,
        });
        let terminal_turn_id = prepared
            .last_turn_finished
            .as_ref()
            .and_then(|event| match event {
                AgentEvent::TurnFinished { turn_id, .. } => Some(turn_id.as_str()),
                _ => None,
            });
        let current_turn_id = active
            .as_ref()
            .map(|(turn_id, _)| turn_id.as_str())
            .or(terminal_turn_id);
        let rerouted = prepared
            .model_rerouted
            .as_ref()
            .and_then(|event| match event {
                AgentEvent::ModelRerouted {
                    turn_id, effective, ..
                } if Some(turn_id.as_str()) == current_turn_id => Some(effective.clone()),
                _ => None,
            });
        let terminal_status = prepared
            .last_turn_finished
            .as_ref()
            .and_then(|event| match event {
                AgentEvent::TurnFinished { status, error, .. } if active.is_none() => {
                    Some(match error {
                        Some(error) => {
                            let concise = format!("turn failed: {}", concise_error(error));
                            (concise.clone(), Some((concise, error.clone())))
                        }
                        None if status != "completed" => (format!("turn {status}"), None),
                        None => ("projection sync".into(), None),
                    })
                }
                _ => None,
            });
        let last_stats = prepared
            .last_turn_finished
            .as_ref()
            .and_then(|event| match event {
                AgentEvent::TurnFinished {
                    input_tokens,
                    output_tokens,
                    cache_read_tokens,
                    tokens_per_second,
                    ..
                } => Some(TokenStats {
                    input: input_tokens.unwrap_or(0),
                    output: output_tokens.unwrap_or(0),
                    cache_read: cache_read_tokens.unwrap_or(0),
                    tokens_per_second: tokens_per_second.unwrap_or(0.0),
                }),
                _ => None,
            });
        let root = prepared.detail.workspace_root.or(prepared.detail.cwd);
        let detail_model = prepared.detail.model;
        batch(|| {
            self.session_title.set(prepared.detail.title);
            if let Some(root) = root.filter(|root| !root.is_empty()) {
                self.cwd.set(root);
            }
            self.turns.set(prepared.turns);
            self.pinned_widgets.set(prepared.pinned);
            self.pending_permissions.set(prepared.permissions);
            // Snapshot permission cards are visibility only; authority belongs
            // only to a locally submitted turn's secret.
            self.active_decision_token.set(None);
            self.browser_active.set(prepared.browser_active);
            self.active_turn_id
                .set(active.as_ref().map(|(id, _)| id.clone()));
            self.streaming.set(active.is_some());
            self.last_turn_tokens.set(last_stats);
            if let Some(model) = rerouted
                .or_else(|| active.and_then(|(_, model)| model))
                .or_else(|| (!detail_model.is_empty()).then_some(detail_model))
            {
                self.model.set(Some(model));
            }
            let (status, detail) =
                terminal_status.unwrap_or_else(|| ("projection sync".to_string(), None));
            self.status.set(status);
            self.status_detail.set(detail);
        });
        // Open tails only after the atomic snapshot install has completed.
        self.connect_projection_tail(
            id.to_string(),
            generation,
            prepared.cursor,
            prepared.lease_id,
        );
        self.connect_canvas_tail(id.to_string(), generation);
        true
    }

    fn connect_projection_tail(
        &self,
        id: String,
        generation: u64,
        initial_cursor: String,
        lease_id: String,
    ) {
        let daemon = self.clone();
        spawn_local(async move {
            if !daemon.projection_generation_is_current(&id, generation) {
                return;
            }
            let encode = |value: &str| {
                js_sys::encode_uri_component(value)
                    .as_string()
                    .unwrap_or_else(|| value.to_string())
            };
            let events_url = format!(
                "{}/v1/agent/projection/events?session_id={}&after_cursor={}&lease_id={}",
                daemon.url.get_untracked().trim_end_matches('/'),
                encode(&id),
                encode(&initial_cursor),
                encode(&lease_id),
            );
            let mut source = match EventSource::new(&events_url) {
                Ok(source) => source,
                Err(error) => {
                    daemon.restart_projection(
                        &id,
                        generation,
                        &format!("tail open failed: {error}"),
                    );
                    return;
                }
            };
            let projection_events = match source.subscribe("session_projection") {
                Ok(stream) => stream,
                Err(error) => {
                    daemon.restart_projection(
                        &id,
                        generation,
                        &format!("tail subscribe failed: {error}"),
                    );
                    return;
                }
            };
            let projection_resets = match source.subscribe("projection_reset") {
                Ok(stream) => stream,
                Err(error) => {
                    daemon.restart_projection(
                        &id,
                        generation,
                        &format!("reset subscribe failed: {error}"),
                    );
                    return;
                }
            };
            // Store while CONNECTING. The browser owns reconnect and sends its
            // Last-Event-ID; replacing this generation explicitly closes it.
            {
                let mut sources = daemon.planner_stream_sources.borrow_mut();
                if sources.session_id != id || sources.generation != generation {
                    return;
                }
                sources.projection = Some(source.clone());
            }
            let mut cursor = initial_cursor;
            let mut stream = futures_util::stream::select(projection_events, projection_resets);
            while let Some(message) = stream.next().await {
                if !daemon.projection_generation_is_current(&id, generation) {
                    return;
                }
                let Ok((event_name, message)) = message else {
                    // gloo-net suppresses transient CONNECTING errors; an error
                    // delivered here is terminal, so a new GET/lease is needed.
                    daemon.restart_projection(&id, generation, "projection tail closed");
                    return;
                };
                if event_name == "projection_reset" {
                    daemon.restart_projection(&id, generation, "daemon projection reset");
                    return;
                }
                let Some(data) = message.data().as_string() else {
                    daemon.restart_projection(&id, generation, "projection frame missing data");
                    return;
                };
                let frame = match serde_json::from_str::<SessionProjectionFrame>(&data) {
                    Ok(frame) => frame,
                    Err(_) => {
                        daemon.restart_projection(
                            &id,
                            generation,
                            "projection frame decode mismatch",
                        );
                        return;
                    }
                };
                match projection_cursor_transition(&cursor, &frame.cursor) {
                    CursorTransition::Duplicate => continue,
                    CursorTransition::Reset => {
                        daemon.restart_projection(
                            &id,
                            generation,
                            "projection cursor gap or prefix change",
                        );
                        return;
                    }
                    CursorTransition::Next => {}
                }
                match frame.source {
                    SessionProjectionSource::Agent => {
                        let event = match serde_json::from_value::<AgentEvent>(frame.event) {
                            Ok(event) if event.session_id() == Some(id.as_str()) => event,
                            _ => {
                                daemon.restart_projection(
                                    &id,
                                    generation,
                                    "agent frame session/decode mismatch",
                                );
                                return;
                            }
                        };
                        apply_event(
                            &event,
                            daemon.turns,
                            daemon.session_id,
                            daemon.streaming,
                            daemon.status,
                            daemon.status_detail,
                            daemon.last_turn_tokens,
                            daemon.session_tokens,
                            daemon.model,
                            daemon.active_turn_id,
                            daemon.browser_active,
                            daemon.browser_last_action,
                            daemon.canvas_patches,
                            daemon.pinned_widgets,
                            daemon.awaiting_session_adoption,
                            daemon.session_title,
                            daemon.cwd,
                        );
                    }
                    SessionProjectionSource::Control => {
                        let event = match serde_json::from_value::<ControlEvent>(frame.event) {
                            Ok(event) => event,
                            Err(_) => {
                                daemon.restart_projection(
                                    &id,
                                    generation,
                                    "control frame decode mismatch",
                                );
                                return;
                            }
                        };
                        daemon
                            .permission_revision
                            .update(|value| *value = value.wrapping_add(1));
                        apply_control_event(&event, &id, daemon.pending_permissions);
                    }
                    SessionProjectionSource::Checkpoint => {
                        let checkpoint = match serde_json::from_value::<SessionProjectionCheckpoint>(
                            frame.event,
                        ) {
                            Ok(checkpoint) => checkpoint,
                            Err(_) => {
                                daemon.restart_projection(
                                    &id,
                                    generation,
                                    "checkpoint decode mismatch",
                                );
                                return;
                            }
                        };
                        match checkpoint_replacement(&checkpoint) {
                            Ok(Some((turns, pinned))) => batch(|| {
                                daemon.turns.set(turns);
                                daemon.pinned_widgets.set(pinned);
                            }),
                            Ok(None) => {}
                            Err(_) => {
                                daemon.restart_projection(
                                    &id,
                                    generation,
                                    "checkpoint requested refetch",
                                );
                                return;
                            }
                        }
                    }
                }
                cursor = frame.cursor;
            }
            // A naturally ended stream is terminal. Native EventSource reconnects
            // do not end subscriptions while CONNECTING.
            daemon.restart_projection(&id, generation, "projection tail ended");
        });
    }

    fn connect_canvas_tail(&self, id: String, generation: u64) {
        let daemon = self.clone();
        spawn_local(async move {
            let events_url = format!(
                "{}/v1/agent/events?session_id={}",
                daemon.url.get_untracked().trim_end_matches('/'),
                js_sys::encode_uri_component(&id)
                    .as_string()
                    .unwrap_or_else(|| id.clone()),
            );
            let mut source = match EventSource::new(&events_url) {
                Ok(source) => source,
                Err(error) => {
                    log::warn!("canvas tail open failed: {error}");
                    return;
                }
            };
            let mut stream = match source.subscribe("surface_patch") {
                Ok(stream) => stream,
                Err(error) => {
                    log::warn!("canvas tail subscribe failed: {error}");
                    return;
                }
            };
            {
                let mut sources = daemon.planner_stream_sources.borrow_mut();
                if sources.session_id != id || sources.generation != generation {
                    return;
                }
                sources.canvas = Some(source.clone());
            }
            while let Some(message) = stream.next().await {
                if !daemon.projection_generation_is_current(&id, generation) {
                    return;
                }
                let Ok((_name, message)) = message else {
                    return;
                };
                let Some(data) = message.data().as_string() else {
                    continue;
                };
                let Ok(event) = serde_json::from_str::<AgentEvent>(&data) else {
                    continue;
                };
                if !is_canvas_lane_event(&event, &id) {
                    // Canvas lane is transport-isolated: no transcript, control,
                    // lifecycle, browser, component, or token event can reduce.
                    continue;
                }
                apply_event(
                    &event,
                    daemon.turns,
                    daemon.session_id,
                    daemon.streaming,
                    daemon.status,
                    daemon.status_detail,
                    daemon.last_turn_tokens,
                    daemon.session_tokens,
                    daemon.model,
                    daemon.active_turn_id,
                    daemon.browser_active,
                    daemon.browser_last_action,
                    daemon.canvas_patches,
                    daemon.pinned_widgets,
                    daemon.awaiting_session_adoption,
                    daemon.session_title,
                    daemon.cwd,
                );
            }
        });
    }

    fn select_session_state(&self, id: &str, title: String) {
