        || path == "/"
        || path.ends_with('/')
        || path.ends_with(".html")
        || path.ends_with("manifest.webmanifest")
    {
        // Shell + worker + manifest: always revalidate, never pin.
        resp.headers_mut().insert(
            header::PRAGMA,
            axum::http::HeaderValue::from_static("no-cache"),
