async fn proxy_agent_sse(state: &AppState, path: &str, req: Request) -> Response {
    let url = agent_sse_upstream_url(&state.daemon_url, path, req.uri().query());
    let mut upstream = state.http.get(&url);
    if let Some(value) = request_last_event_id(&req) {
        upstream = upstream.header("Last-Event-ID", value);
    }
