async fn session(
    State(state): State<AppState>,
    Path(session_id): Path<SessionId>,
) -> (StatusCode, Json<SessionResponse>) {
    match state.runtime.session_detail(session_id) {
        Ok(mut session) => {
            // A persistence rename and its internal checkpoint cross an async
            // bridge. Bound the alignment wait; never return a cursor for a
            // different file revision. Legacy clients still receive the normal
            // session body if the projection is momentarily unavailable.
            let mut projection = None;
            if let Some(store) = state.agent_events.projection() {
                for attempt in 0..=20 {
                    match store.snapshot(
                        &session_id.to_string(),
                        session.persistence_revision,
                        normalized_projection_checkpoint(&session),
                    ) {
                        Ok(snapshot) => {
                            projection = Some(snapshot);
                            break;
                        }
                        Err(session_projection::ProjectionReset::RevisionMismatch)
                            if attempt < 20 =>
                        {
                            tokio::time::sleep(std::time::Duration::from_millis(5)).await;
                            match state.runtime.session_detail(session_id) {
                                Ok(refreshed) => session = refreshed,
                                Err(_) => break,
                            }
                        }
                        Err(reset) => {
                            tracing::warn!(%session_id, reason = reset.reason(), "session projection snapshot unavailable");
                            break;
                        }
                    }
                }
            }
            enrich_session_detail(&state, &mut session).await;
            (
                StatusCode::OK,
                Json(SessionResponse {
                    ok: true,
                    session: Some(session),
                    projection,
                    error: None,
                }),
            )
        }
        Err(error) if is_not_found(&error) => (
            StatusCode::NOT_FOUND,
            Json(SessionResponse {
                ok: false,
                session: None,
                projection: None,
                error: Some("session not found".into()),
            }),
        ),
        Err(error) => {
            tracing::warn!(%session_id, error = %error, "failed to read session detail");
            (
                StatusCode::INTERNAL_SERVER_ERROR,
                Json(SessionResponse {
                    ok: false,
                    session: None,
                    projection: None,
                    error: Some("session could not be read".into()),
                }),
            )
        }
    }
}

