5509	    // Index `component_render` tool-CALL args by tool_call_id so a `component_render`
5510	    // tool-RESULT entry in the transcript can recover its props. The transcript
5511	    // text for these results is only the daemon's summary ("rendered component
5512	    // 'x'…") — the actual id/kind/props live solely in the call arguments
5513	    // (OCEAN-382). We also note `component_unmount` calls so a persisted unmount
5514	    // removes the component on replay, mirroring the live SSE reducer.
5515	    let render_calls: std::collections::HashMap<&str, &SessionToolContext> = tool_context
5516	        .iter()
5517	        .filter(|c| {
5518	            c.kind == "call"
5519	                && (c.tool_name == "component_render" || c.tool_name == "component_unmount")
5520	        })
